UNDECIDED_SUBMITTED = ("AUTH_RUNNING", "AUTH_FAILED", "REVIEW_PENDING", "AWAITING_APPLICANT", "SCORING", "DECISION_PENDING")


def give_cases_their_reviewers(apps, schema_editor):
    """Cases already under way go to whoever last ruled on them (if they still work on that
    department); decided ones record who decided them. The rest start untaken."""
    Assessment = apps.get_model("cases", "Assessment")
    Ruling = apps.get_model("cases", "Ruling")
    Decision = apps.get_model("cases", "Decision")
    for decision in Decision.objects.select_related("assessment"):
        Assessment.objects.filter(pk=decision.assessment_id).update(reviewer=decision.reviewer_id, claimed_at=decision.decided_at)
    for case in Assessment.objects.filter(stage__in=UNDECIDED_SUBMITTED):
        ruling = (
            Ruling.objects.filter(submission__assessment=case).select_related("reviewer")
            .order_by("-created_at").first()
        )
        if ruling is None:
            continue
        who = ruling.reviewer
        works_here = who.is_active and (
            who.role == "superuser" or (who.role == "reviewer" and who.departments.filter(pk=case.department_id).exists())
        )
        if works_here and who.pk != case.applicant_id:
            Assessment.objects.filter(pk=case.pk).update(reviewer=who, claimed_at=ruling.created_at)
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")


